function diploIco(s){const has=new Set();(s.items||[]).forEach(i=>itemTopics(i).forEach(k=>has.add(k)));const ks=['dip','sanc','aid'].filter(k=>has.has(k));if(!ks.length)ks.push('dip');const n=ks.length,P=2.5,D=n*P,f=x=>+(x/D).toFixed(4);let body='';if(n===1){body=DIPLO_SYM[ks[0]]}else{body=ks.map((k,i)=>`<g opacity="0"><animate attributeName="opacity" values="0;1;1;0;0" keyTimes="0;${f(.225)};${f(2.25)};${f(P)};1" dur="${D}s" begin="${i*P}s" repeatCount="indefinite"/>${DIPLO_SYM[k]}</g>`).join('')+'<g fill="#8fb6e4">'+ks.map((k,i)=>`<circle cx="${64+(i-(n-1)/2)*12}" cy="112" r="3.2" opacity="0.3"><animate attributeName="opacity" values="1;1;0.3;0.3" keyTimes="0;${f(P)};${f(P+.01)};1" dur="${D}s" begin="${i*P}s" repeatCount="indefinite"/></circle>`).join('')+'</g>'}const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" width="128" height="128"><defs><radialGradient id="bg" cx="0.5" cy="0.4" r="0.7"><stop offset="0" stop-color="#1f2f45"/><stop offset="1" stop-color="#0c121b"/></radialGradient><clipPath id="disc"><circle cx="64" cy="64" r="64"/></clipPath></defs><g clip-path="url(#disc)"><rect width="128" height="128" fill="url(#bg)"/>${body}</g></svg>`;return `<span class="sec-ico img" aria-hidden="true"><img src="data:image/svg+xml,${encodeURIComponent(svg)}" alt="" width="30" height="30"></span>`}
const ICO=(id,s)=>(id==='diplo'&&s)?diploIco(s):(SEC_ICON[id]&&SEC_SVG[id])?`<span class="sec-ico img" aria-hidden="true">${SEC_ICON[id]}</span>`:SEC_SVG[id]?`<span class="sec-ico col" aria-hidden="true"><svg viewBox="0 0 24 24" width="22" height="22">${SEC_SVG[id]}</svg></span>`:(ICO_P[id]&&!SEC_ICON[id])?`<span class="sec-ico" aria-hidden="true"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICO_P[id]}</svg></span>`:(SEC_ICON[id]?`<span class="sec-ico img" aria-hidden="true">${SEC_ICON[id]}</span>`:'');
