  if(!cur){body.innerHTML=`<p class="map-src">У звіті Повітряних сил за цю ніч немає кількості засобів атаки.</p>`;return}
  const S=atkSum(cur.mix);const tot=cur.mix.reduce((a,m)=>a+m.n,0);
  const rows=cur.mix.map(m=>{const p=PCFG.types[m.type]||{label:m.type,low:null,high:null,src:'ціну не знайдено'};const lo=p.low!=null?m.n*p.low:null,hi=p.high!=null?m.n*p.high:null;
    return `<tr><td>${esc(p.label)}<small class="src">${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.src)}</a>`:esc(p.src)}</small></td><td class="n">${fmt(m.n)}</td><td class="n">${p.low==null?'—':p.low===p.high?money(p.low):money(p.low)+'–'+money(p.high)}</td><td class="n">${lo==null?'—':lo===hi?money(lo):money(lo)+'–'+money(hi)}</td></tr>`}).join('');
