  const gs=B.losses&&B.losses.gsTotal;const pers=gs&&num(gs.personnel);
  const net=A.ds_occ-base,netI=A.isw-base;if(!(net>0)){body.innerHTML=`<p class="map-src">${esc(t.err)}</p>`;return}
