/* ---------- SBS snapshot ---------- */
function sbsAsOfTxt(S){const a=S&&S.asOf?new Date(S.asOf):null;return a&&!isNaN(a)?a.toLocaleString(lang==='en'?'en-GB':'uk-UA',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}):((S&&S.asof)||'—')}
function sbsDigestHTML(){const S=D.sbs;if(!S)return '';const t=T();const P=S.personnel||{},TT=S.totals||{};
  const st=S.stats||[{label:t.sbsPHit,value:P.hit},{label:t.sbsPKilled,value:P.killed},{label:t.sbsPWounded,value:P.wounded}];
  return `<section class="sec" id="sec-sbs"><div class="sech"><h2>${ICO('sbs')}<span>${esc(noFlag(lang==='en'?t.sbs:(S.title||t.sbs)))}</span></h2><span>${t.sbsAsOf} ${esc(sbsAsOfTxt(S))}</span></div>
  <div class="item"><div class="sbs-row">${st.map(x=>`<div><small>${esc(x.label)}</small><b>${x.value==null?'—':fmt(x.value)}</b></div>`).join('')}</div>
  ${TT.hit!=null?`<p class="cred" style="margin-top:6px">${t.sbsHit}: ${fmt(TT.hit)} · ${t.sbsDestroyed}: ${fmt(TT.destroyed)} · ${t.sbsStrike}: ${fmt(TT.strikeSorties)} · ${t.sbsRecon}: ${fmt(TT.reconSorties)}</p>`:''}
  <p class="note" style="margin:6px 0 0">${esc(S.period||'')} ${esc(S.note||'')}</p><span class="cred">${esc(S.source||'')}${S.url?` · <a href="${esc(S.url)}" target="_blank" rel="noopener">${esc(S.url)}</a>`:''}</span></div></section>`}
function sbsShell(){const S=D.sbs||(LATEST&&LATEST.sbs);if(!S)return '';const t=T();
  const asOf=S.asOf?new Date(S.asOf):null;const asOfTxt=sbsAsOfTxt(S);
  const stale=asOf&&(dayN(D.date)-dayN(S.asOf.slice(0,10)))>1;
  const cats=(S.categories||[]).filter(c=>(c.hit||0)>0).sort((a,b)=>b.hit-a.hit);const zero=(S.categories||[]).filter(c=>!(c.hit>0)).map(c=>c.label);
  const mx=Math.max(1,...cats.map(c=>c.hit));const T_=S.totals||{},P=S.personnel||{};
  const tile=(l,v,sub)=>`<div class="tile"><small>${l}</small><b>${v==null?'—':fmt(v)}</b><span>${sub||''}</span></div>`;
  return `<section class="tlwrap" id="sbs"><div class="tl-head"><h2>${t.sbs}</h2><p>${esc(S.period||'')}${S.month?' · '+esc(S.month):''} · ${t.sbsAsOf} ${esc(asOfTxt)} ${stale?`<span class="chip part">${t.sbsStale}</span>`:''}</p></div>
  <div class="tiles">${tile(t.sbsHit,T_.hit)}${tile(t.sbsDestroyed,T_.destroyed)}${tile(t.sbsStrike,T_.strikeSorties)}${tile(t.sbsRecon,T_.reconSorties)}</div>
  <div class="tiles sbs-p">${tile(t.sbsPHit,P.hit,t.sbsPNote)}${tile(t.sbsPKilled,P.killed)}${tile(t.sbsPWounded,P.wounded)}</div>
  <div class="panel"><h2>${t.sbsCats}</h2><div class="legend"><span><i style="background:var(--s1)"></i>${t.sbsLegD}</span><span><i style="background:var(--s2)"></i>${t.sbsLegH}</span></div>
   <div class="bars sbs-bars">${cats.map(c=>`<div class="bar" tabindex="0" data-tip="${esc(c.label)}: ${t.sbsTipH} ${c.hit}, ${t.sbsTipD} ${c.destroyed}"><span class="lbl">${esc(c.label)}</span><span class="stack" style="width:${c.hit/mx*100}%"><div style="width:${c.destroyed/c.hit*100}%"></div><div style="flex:1"></div></span><span class="val">${fmt(c.destroyed)} / ${fmt(c.hit)}</span></div>`).join('')}</div>
   ${zero.length?`<p class="sub" style="margin:0">${t.sbsZero} ${esc(zero.join(', '))}.</p>`:''}
   <p class="sub" style="margin:0">${esc(S.note||'')} <a href="${esc(S.url)}" target="_blank" rel="noopener">${t.sbsLink}</a></p></div></section>`}
