/* ---------- exports ---------- */
function toMD(){const L=[];L.push('# Щоденний дайджест війни',`**${D.weekday}, ${D.dateLabel}**`,'',...(D.headline&&D.headline.title?[`**${D.headline.kicker||'Головне'}: ${D.headline.title}**`,'',D.headline.text||'','','**Також за добу:**']:[]),...(Array.isArray(D.ledeParts)&&D.ledeParts.length?D.ledeParts.map(x=>`- ${x.label?'**'+x.label+':** ':''}${x.text}`):[D.lede]),'');
  sinceList('uk').forEach(x=>L.push(`- **${x.label}** (${x.fd}): ${x.span}, ${x.day}-й день`));L.push('');
  D.sections.filter(s=>s.items&&s.items.length).forEach(s=>{L.push(`## ${s.title}`,'');s.items.forEach(i=>{L.push(`- ${i.emoji?i.emoji+' ':''}${i.unverified?'**[непідтверджено]** ':''}${i.text}`);if(Array.isArray(i.list))i.list.forEach(x=>L.push(`  - ${x}`));if(i.quote)L.push(`  > ${i.quote.en} — ${i.quote.uk}`);if(i.local&&i.local.verdict)L.push(`  _${UI.uk.loc[i.local.verdict]||i.local.verdict}${i.local.who?' ('+i.local.who+(i.local.when?', '+i.local.when:'')+')':''}: ${i.local.said||''}_`);L.push(`  _Джерело: ${i.source}_`)});L.push('')});
  L.push('## Розбіжності джерел','',D.divergences.intro,'');D.divergences.items.forEach(x=>{L.push(`### ${x.title}`,`- ${x.a.source}: ${x.a.claim}`,`- ${x.b.source}: ${x.b.claim}`,'',x.why,'')});
  {const B=LATEST||D;const r=B.losses&&(B.losses.series||[]).find(e=>e.date===D.date);if(r){L.push('## Втрати: заяви сторін','',B.losses.caveat||'','');
    L.push(`- Втрати росії за добу (Генштаб ЗСУ): ${r.ru&&r.ru.personnel!=null?r.ru.personnel:'—'} осіб`);L.push(`- Втрати України за добу (заява Міноборони рф, сума по угрупованнях): ${r.ua&&r.ua.personnel!=null?'≈ '+r.ua.personnel:'—'} осіб`,'')}}
  {const S=false&&(D.sbs||(LATEST&&LATEST.sbs));if(S){L.push('## Сили безпілотних систем',`_${S.period||''}, станом на ${S.asOf||'—'}_`,'',`- Уражено цілей: ${S.totals.hit}, у т.ч. знищено: ${S.totals.destroyed}`,`- ОС РОВ: уражено ${S.personnel.hit}, знищено ${S.personnel.killed}, поранено ${S.personnel.wounded}`,`- Джерело: ${S.url}`,'')}}
  L.push(`_${(D.since[0]||{}).note||''}. Лічба днів включає день початку._`,'','## Джерела','');
  D.sources.forEach(s=>L.push(`- [${s.title}](${s.url})${s.note?` (${s.note})`:''}`));L.push('',D.unavailable,'',D.assumption,'',`_${D.footer}_`,'');return L.join('\n')}
function toPrintHTML(){const keep=lang;lang='uk';const dt=dateTitle();const body=`<p class="eb">Щоденний дайджест війни · ${esc(dt.line)}</p><h1>${esc(dt.h)}</h1>${ledeHTML()}<p class="eb">${sinceList('uk').map(x=>`${esc(x.label)} (${x.fd}): ${esc(x.span)}, ${x.day}-й день`).join(' · ')}</p>`+renderDigest().replace(/<div class="tools"[\s\S]*?<\/div>/,'');lang=keep;
  return `<!doctype html><html lang="uk"><head><meta charset="utf-8"><title>Щоденний дайджест війни — ${esc(D.dateLabel)}</title><style>body{font:15px/1.55 Georgia,serif;max-width:720px;margin:24px auto;padding:0 16px;color:#111}h1{font-size:26px;margin:4px 0}h2{font:600 13px Arial,sans-serif;text-transform:uppercase;letter-spacing:.08em;margin:0}.sech{display:flex;justify-content:space-between;border-bottom:1px solid #111;padding-bottom:3px;margin-top:22px}.sech>span{font:11px monospace;color:#666}.sec-ico{display:none}.item{padding:8px 0;border-bottom:1px solid #ddd;break-inside:avoid}.item p{margin:0}.ilist{margin:4px 0 0;padding-left:20px}.quote{margin:4px 0;padding-left:10px;border-left:2px solid #555}.quote span{display:block}.quote .uk{color:#555;font-size:14px}.cred{font:12px Arial,sans-serif;color:#555}.chip{font:700 10px Arial,sans-serif;text-transform:uppercase;margin-right:6px;color:#97302c}.diverge{border:1px solid #111;padding:10px 14px;margin-top:22px}.dv{border-top:1px solid #ddd;padding:8px 0;break-inside:avoid}.dv h3{font-size:16px;margin:0 0 4px}.vs{display:flex;gap:8px}.vs>div{flex:1;background:#f1f1ef;padding:6px 8px}.vs small{display:block;font:11px Arial,sans-serif;color:#555}.vs i{align-self:center;font:11px monospace}.srcs{padding-left:18px;font-size:13px;overflow-wrap:anywhere}.srcs em{display:block;font:11px Arial,sans-serif;color:#555;font-style:normal}.note,.intro{font-size:13px;color:#444}.eb,.lede{margin:4px 0}.lede-parts p{margin:3px 0}.cv-grid{display:flex;gap:16px}.cv-fig{flex:1;margin:0}.cv-fig svg{width:100%}.cv-x{font:9px Arial;fill:#555}.cv-v{font:bold 10px Arial;fill:#111}.cv-base{stroke:#999}.cv-src{font:11px Arial;color:#555}.kick{font:700 10px Arial,sans-serif;text-transform:uppercase;color:#555}.lede-h{font-size:19px;font-weight:700;margin:2px 0}.lede-more{display:none}.lede-also{margin-top:8px}.lede-parts b{font:700 10px Arial,sans-serif;text-transform:uppercase;color:#555;margin-right:6px}.eb{font:12px Arial,sans-serif;color:#555}.foot{margin-top:20px;font-style:italic;color:#444}.sbs-row{display:flex;gap:12px}.sbs-row>div{flex:1}.sbs-row small{display:block;font:11px Arial,sans-serif;color:#555}.sbs-row b{font:500 20px monospace}.lang-note{display:none}</style></head><body>${body}</body></html>`}
let dl=null;
async function wireDownloads(){const bar=document.getElementById('tools');if(!bar)return;if(!dl)return;bar.hidden=false;const msg=document.getElementById('msg');
  async function go(name,data){msg.textContent='';try{const r=await dl.save({filename:name,data});msg.textContent=r&&r.status==='saved'?T().saved:T().sent}catch(e){msg.textContent=e&&e.code==='declined'?T().declined:T().failed}}
  document.getElementById('dlmd').onclick=()=>go('digest-'+D.date+'.md',toMD());
  document.getElementById('dlhtml').onclick=()=>go('digest-'+D.date+'.html',toPrintHTML());}

/* ---------- bridge: React (components/dash/Dashboard.tsx) owns state, routing and the page shell ---------- */
async function fetchIssue(date){if(LATEST&&date===LATEST.date)return LATEST;if(CACHE[date])return CACHE[date];
  const r=await fetch('issues/'+date+'.json',{cache:'no-store'});if(!r.ok)throw new Error(r.status);const j=styleData(await r.json(),'');if(!j||j.date!==date)throw new Error('mismatch');CACHE[date]=j;return j}
